import random
random.seed(5)
records = [{"a": 1, "b": 2} if random.random() < 0.9 else {"a": 1} for _ in range(2000)]
sample = random.sample(records, 500)
presence = {}
for r in sample:
    for k in r: presence[k] = presence.get(k, 0) + 1
for k, n in presence.items():
    print("field %r present in %.1f%% of sample" % (k, 100.0 * n / len(sample)))

